typescript.c.ts:
declare const llm: { invoke(input: unknown): Promise<unknown> };

const MAX_RETRIES = 3;

export async function call(p: unknown, attempt = 0): Promise<unknown> {
  try {
    return await llm.invoke(p);
  } catch {
    if (attempt < MAX_RETRIES) {
      return call(p, attempt + 1);
    }
  }
}

