import OpenAI from "openai";

const client = new OpenAI();

/** In-memory store of support articles keyed by id. */
export class DocumentStore {
  private docs = new Map<string, string>();

  /** Add or replace an article. */
  add(docId: string, text: string): void {
    this.docs.set(docId, text);
  }

  /** Return up to `limit` articles containing any query term. */
  search(query: string, limit = 3): string[] {
    const terms = query.toLowerCase().split(/\s+/);
    const hits = [...this.docs.values()].filter((t) => terms.some((w) => t.toLowerCase().includes(w)));
    return hits.slice(0, limit);
  }
}

/** Answer a question using the top matching articles as context. */
export async function answer(store: DocumentStore, question: string): Promise<string> {
  const context = store.search(question).join("\n---\n");
  const resp = await client.chat.completions.create({ model: "gpt-4o-mini", messages: [
    { role: "system", content: "Answer using only this context:\n" + context },
    { role: "user", content: question },
  ] });
  return resp.choices[0].message.content ?? "";
}

