import anthropic

client = anthropic.Anthropic()
QUEUES = {"billing": "finance-team", "bug": "eng-oncall", "other": "support-l1"}


def _normalize(text: str) -> str:
    return " ".join(text.split())


def _complete(system: str, content: str, max_tokens: int) -> str:
    msg = client.messages.create(model="claude-sonnet-4-5", max_tokens=max_tokens, system=system,
                                 messages=[{"role": "user", "content": content}])
    return msg.content[0].text


def classify_ticket(body: str) -> str:
    """Classify a support ticket as billing, bug, or other."""
    label = _complete("Reply with exactly one word: billing, bug, or other.", _normalize(body), 10).strip().lower()
    return label if label in QUEUES else "other"


def route_ticket(body: str) -> str:
    """Return the queue a ticket should be assigned to."""
    return QUEUES[classify_ticket(body)]


def summarize_thread(messages: list[str]) -> str:
    """Produce a two-sentence summary of a ticket's message thread."""
    return _complete("Summarize this support thread in two sentences.", "\n\n".join(messages), 200)

