import Anthropic from "@anthropic-ai/sdk";

const client = new Anthropic();
const queues: Record<string, string> = { billing: "finance-team", bug: "eng-oncall", other: "support-l1" };

function normalize(text: string): string {
  return text.split(/\s+/).filter(Boolean).join(" ");
}

async function complete(system: string, content: string, maxTokens: number): Promise<string> {
  const msg = await client.messages.create({ model: "claude-sonnet-4-5", max_tokens: maxTokens, system, messages: [{ role: "user", content }] });
  const block = msg.content[0];
  return block.type === "text" ? block.text : "";
}

/** Classify a support ticket as billing, bug, or other. */
export async function classifyTicket(body: string): Promise<string> {
  const label = (await complete("Reply with exactly one word: billing, bug, or other.", normalize(body), 10)).trim().toLowerCase();
  return label in queues ? label : "other";
}

/** Return the queue a ticket should be assigned to. */
export async function routeTicket(body: string): Promise<string> {
  return queues[await classifyTicket(body)];
}

/** Produce a two-sentence summary of a ticket's message thread. */
export async function summarizeThread(messages: string[]): Promise<string> {
  return complete("Summarize this support thread in two sentences.", messages.join("\n\n"), 200);
}

