def get_forecast(city: str) -> dict:
    r = requests.get("https://api.weather.example/v1/forecast", params={"q": city})
    r.raise_for_status()
    return r.json()


def format_forecast(data: dict) -> str:
    return f"{data['city']}: {data['summary']}, high {data['high']}C"


def run_agent(question: str) -> str:
    resp = client.chat.completions.create(model="gpt-4o-mini", messages=[{"role": "user", "content": question}], tools=TOOLS)
    msg = resp.choices[0].message
    if not msg.tool_calls:
        return msg.content
    args = json.loads(msg.tool_calls[0].function.arguments)
    return format_forecast(get_forecast(args["city"]))

