import OpenAI from "openai";
import type { ChatCompletionTool } from "openai/resources/chat/completions";

const client = new OpenAI();
const tools: ChatCompletionTool[] = [{ type: "function", function: {
  name: "getForecast",
  parameters: { type: "object", properties: { city: { type: "string" } }, required: ["city"] },
} }];

export interface Forecast { city: string; summary: string; high: number }

// fetch forecast from the weather API
export async function getForecast(city: string): Promise<Forecast> {
  const res = await fetch(`https://api.weather.example/v1/forecast?q=${encodeURIComponent(city)}`);
  if (!res.ok) throw new Error(`weather API returned ${res.status}`);
  return (await res.json()) as Forecast;
}

export function formatForecast(data: Forecast): string {
  return `${data.city}: ${data.summary}, high ${data.high}C`;
}

export async function runAgent(question: string): Promise<string | null> {
  const resp = await client.chat.completions.create({ model: "gpt-4o-mini", messages: [{ role: "user", content: question }], tools });
  const msg = resp.choices[0].message;
  if (!msg.tool_calls?.length) return msg.content;
  const args = JSON.parse(msg.tool_calls[0].function.arguments);
  return formatForecast(await getForecast(args.city));
}

