export class Turn {
  constructor(public role: string, public content: string, public at: Date = new Date()) {}
}

/** Rolling window of recent conversation turns. */
export class ConversationMemory {
  turns: Turn[] = [];

  constructor(private maxTurns = 20) {}

  append(role: string, content: string): void {
    this.turns.push(new Turn(role, content));
    this.turns = this.turns.slice(-this.maxTurns);
  }

  asMessages(): { role: string; content: string }[] {
    return this.turns.map((t) => ({ role: t.role, content: t.content }));
  }

  lastUserMessage(): string | undefined {
    return this.turns.findLast((t) => t.role === "user")?.content;
  }
}

