PUBLIC_KEY = os.environ["JWT_PUBLIC_KEY"]
REQUIRED_SCOPES = {
    "read_calendar": "calendar:read",
    "create_event": "calendar:write",
    "delete_event": "calendar:write",
}


class InsufficientScope(PermissionError):
    pass


def check_scope(token: str, tool_name: str) -> None:
    claims = jwt.decode(token, PUBLIC_KEY, algorithms=["RS256"], audience="calendar-agent")
    granted = set(claims.get("scope", "").split())
    needed = REQUIRED_SCOPES.get(tool_name)
    if needed is None or needed not in granted:
        raise InsufficientScope(f"{tool_name} requires {needed}")


def call_tool(token: str, tool_name: str, args: dict, tools: dict):
    check_scope(token, tool_name)
    return tools[tool_name](**args)

