import { importSPKI, jwtVerify } from "jose";

const publicKey = await importSPKI(process.env.JWT_PUBLIC_KEY!, "RS256");
const requiredScopes: Record<string, string> = {
  readCalendar: "calendar:read",
  createEvent: "calendar:write",
  deleteEvent: "calendar:write",
};

export class InsufficientScopeError extends Error {}

export async function checkScope(token: string, toolName: string): Promise<void> {
  const { payload } = await jwtVerify(token, publicKey, { audience: "calendar-agent" });
  const granted = new Set(String(payload.scope ?? "").split(" "));
  const needed = requiredScopes[toolName];
  if (!needed || !granted.has(needed)) {
    throw new InsufficientScopeError(`${toolName} requires ${needed}`);
  }
}

type Tool = (args: Record<string, unknown>) => Promise<unknown>;

export async function callTool(token: string, toolName: string, args: Record<string, unknown>, tools: Record<string, Tool>) {
  await checkScope(token, toolName);
  return tools[toolName](args);
}

