const TOKEN_URL = "https://auth.example.com/oauth/token";
const REFRESH_MARGIN_MS = 60_000;

export class TokenManager {
  private token?: string;
  private expiresAt = 0;

  constructor(private clientId: string, private clientSecret: string) {}

  async getToken(): Promise<string> {
    if (!this.token || Date.now() >= this.expiresAt - REFRESH_MARGIN_MS) {
      await this.refresh();
    }
    return this.token!;
  }

  private async refresh(): Promise<void> {
    const res = await fetch(TOKEN_URL, {
      method: "POST",
      body: new URLSearchParams({ grant_type: "client_credentials", client_id: this.clientId, client_secret: this.clientSecret }),
    });
    if (!res.ok) throw new Error(`token endpoint returned ${res.status}`);
    const body = (await res.json()) as { access_token: string; expires_in: number };
    this.token = body.access_token;
    this.expiresAt = Date.now() + body.expires_in * 1000;
  }
}

