import OpenAI from "openai";
import type { ChatCompletionMessageParam, ChatCompletionMessageToolCall, ChatCompletionTool } from "openai/resources/chat/completions";

const client = new OpenAI();
const AGENT_TIMEOUT_MS = 120_000;
const MAX_STEPS = 8;

export async function runAgent(
  messages: ChatCompletionMessageParam[],
  tools: ChatCompletionTool[],
  execute: (call: ChatCompletionMessageToolCall) => Promise<string>,
): Promise<string | null> {
  const signal = AbortSignal.timeout(AGENT_TIMEOUT_MS);
  for (let step = 0; step < MAX_STEPS; step++) {
    signal.throwIfAborted();
    const resp = await client.chat.completions.create({ model: "gpt-4o", messages, tools }, { signal });
    const msg = resp.choices[0].message;
    if (!msg.tool_calls?.length) return msg.content;
    messages.push(msg);
    for (const call of msg.tool_calls) {
      messages.push({ role: "tool", tool_call_id: call.id, content: await execute(call) });
    }
  }
  throw new Error("agent exceeded max steps");
}

