import Database from "better-sqlite3";

// FEHA (Cal. Code Regs. tit. 2, sec. 11013) - keep applicant records and automated-decision data for 4 years.
const CANDIDATE_RECORD_RETENTION_YEARS = 4;

const db = new Database("hiring.db");

export function saveScreeningDecision(candidateId: string, requisitionId: string, decision: string, modelOutput: unknown): void {
  const decidedAt = new Date();
  const retainUntil = new Date(decidedAt);
  retainUntil.setUTCFullYear(retainUntil.getUTCFullYear() + CANDIDATE_RECORD_RETENTION_YEARS);
  db.prepare(
    "INSERT INTO screening_decisions (candidate_id, requisition_id, decision, model_output, decided_at, retain_until)" +
      " VALUES (?, ?, ?, ?, ?, ?)",
  ).run(candidateId, requisitionId, decision, JSON.stringify(modelOutput), decidedAt.toISOString(), retainUntil.toISOString());
}

export function purgeExpiredCandidateRecords(): number {
  const now = new Date().toISOString();
  return db.prepare("DELETE FROM screening_decisions WHERE retain_until < ? AND legal_hold = 0").run(now).changes;
}

