import { PutObjectCommand, S3Client } from "@aws-sdk/client-s3";

const s3 = new S3Client({});
const BUCKET = "acme-hiring-records";
// California FEHA: applicant and screening records must be kept for at least 4 years.
const CANDIDATE_RECORD_RETENTION_YEARS = 4;

export async function archiveScreeningResult(candidateId: string, requisitionId: string, result: Record<string, unknown>): Promise<string> {
  const now = new Date();
  const retainUntil = new Date(now);
  retainUntil.setUTCFullYear(now.getUTCFullYear() + CANDIDATE_RECORD_RETENTION_YEARS);
  const key = `screening/${requisitionId}/${candidateId}.json`;
  await s3.send(new PutObjectCommand({
    Bucket: BUCKET,
    Key: key,
    Body: JSON.stringify({ ...result, archivedAt: now.toISOString() }),
    ContentType: "application/json",
    ObjectLockMode: "COMPLIANCE",
    ObjectLockRetainUntilDate: retainUntil,
  }));
  return key;
}

