const DEFAULT_AREA_HIRE_RATE = 0.05;

export interface Candidate { id: string; yearsExperience: number; skillsMatch: number; interviewScore: number; postalCode: string }
export interface PastApplication { postalCode: string; hired: boolean }
export interface ScreeningModel { predict(features: number[][]): number[] }

export function postalCodeHireRates(pastApplications: PastApplication[]): Map<string, number> {
  const totals = new Map<string, [number, number]>();
  for (const app of pastApplications) {
    const [seen, hired] = totals.get(app.postalCode) ?? [0, 0];
    totals.set(app.postalCode, [seen + 1, hired + (app.hired ? 1 : 0)]);
  }
  return new Map([...totals].map(([code, [seen, hired]]) => [code, hired / seen]));
}

function candidateFeatures(c: Candidate, areaRates: Map<string, number>): number[] {
  return [c.yearsExperience, c.skillsMatch, c.interviewScore, areaRates.get(c.postalCode) ?? DEFAULT_AREA_HIRE_RATE];
}

export function rankCandidates(model: ScreeningModel, candidates: Candidate[], pastApplications: PastApplication[]): Candidate[] {
  const areaRates = postalCodeHireRates(pastApplications);
  const scores = model.predict(candidates.map((c) => candidateFeatures(c, areaRates)));
  return candidates.map((c, i) => ({ c, s: scores[i] })).sort((a, b) => b.s - a.s).map(({ c }) => c);
}

