        (user_id, purpose, int(granted), datetime.now(timezone.utc).isoformat()),
    )
    db.commit()

def withdraw_consent(user_id: str, purpose: str) -> None:
    record_consent(user_id, purpose, False)

def has_consent(user_id: str, purpose: str) -> bool:
    row = db.execute(
        "SELECT granted FROM consent_records WHERE user_id = ? AND purpose = ? ORDER BY recorded_at DESC LIMIT 1",
