import Database from "better-sqlite3";
import OpenAI from "openai";

const client = new OpenAI();
const db = new Database("app.db");

export function recordConsent(userId: string, purpose: string, granted: boolean): void {
  db.prepare("INSERT INTO consent_records (user_id, purpose, granted, recorded_at) VALUES (?, ?, ?, ?)")
    .run(userId, purpose, granted ? 1 : 0, new Date().toISOString());
}

export function withdrawConsent(userId: string, purpose: string): void {
  recordConsent(userId, purpose, false);
}

