  const row = db
    .prepare("SELECT granted FROM consent_records WHERE user_id = ? AND purpose = ? ORDER BY recorded_at DESC LIMIT 1")
    .get(userId, purpose) as { granted: number } | undefined;
  return row?.granted === 1;
}

export async function personalizeReply(userId: string, message: string): Promise<string> {
  if (!hasConsent(userId, "aiPersonalization")) {
    throw new Error("User has not consented to AI personalization");
  }
  const resp = await client.chat.completions.create({ model: "gpt-4o-mini", messages: [{ role: "user", content: message }] });
  return resp.choices[0].message.content ?? "";
}

