import express from "express";
import pg from "pg";
import { Pinecone } from "@pinecone-database/pinecone";

const pool = new pg.Pool({ connectionString: process.env.DATABASE_URL });
const memoryIndex = new Pinecone().index("chat-memory");
export const app = express();

export async function deleteUserData(userId: string): Promise<void> {
  const db = await pool.connect();
  try {
    await db.query("BEGIN");
    for (const sql of ["DELETE FROM chat_messages WHERE user_id = $1", "DELETE FROM user_preferences WHERE user_id = $1", "DELETE FROM users WHERE id = $1"]) {
      await db.query(sql, [userId]);
    }
    await db.query("INSERT INTO erasure_requests (completed_at) VALUES (now())");
    await db.query("COMMIT");
  } catch (err) {
    await db.query("ROLLBACK");
    throw err;
  } finally {
    db.release();
  }
  await memoryIndex.namespace(`user-${userId}`).deleteAll();
}

app.delete("/users/:userId/data", async (req, res) => {
  await deleteUserData(req.params.userId);
  res.sendStatus(204);
});

