import { AzureOpenAI } from "openai";
import { S3Client, PutObjectCommand } from "@aws-sdk/client-s3";

// Claim files contain EU personal data and must be processed and stored in the EEA only.
const ALLOWED_REGIONS = new Set(["swedencentral", "westeurope", "francecentral"]);
const region = process.env.AZURE_OPENAI_REGION ?? "";
if (!ALLOWED_REGIONS.has(region)) {
  throw new Error(`Region ${region} is outside the EU; refusing to start`);
}

const client = new AzureOpenAI({
  endpoint: `https://claims-${region}.openai.azure.com`,
  apiKey: process.env.AZURE_OPENAI_API_KEY,
  apiVersion: "2024-06-01",
});
const s3 = new S3Client({ region: "eu-central-1" });

export async function summarizeClaim(claimId: string, claimText: string): Promise<string> {
  const resp = await client.chat.completions.create({
    model: "gpt-4o",
    messages: [{ role: "user", content: `Summarize this insurance claim:\n${claimText}` }],
  });
  const summary = resp.choices[0].message.content ?? "";
  await s3.send(new PutObjectCommand({ Bucket: "claims-summaries-eu", Key: `${claimId}.txt`, Body: summary }));
  return summary;
}

