from datetime import date

from openai import OpenAI

client = OpenAI()
log = logging.getLogger(__name__)

# High-risk processing operations need a signed-off DPIA before they may run.
DPIA_REGISTER = {
    "credit_limit_scoring": {"dpia_id": "DPIA-2026-014", "approved_on": date(2026, 3, 2),
                             "review_due": date(2027, 3, 2), "approved_by": "dpo@example.eu"},
}

def require_dpia(operation: str) -> dict:
    dpia = DPIA_REGISTER.get(operation)
    if dpia is None:
        raise PermissionError(f"No DPIA on record for {operation}")
    if dpia["review_due"] < date.today():
        raise PermissionError(f"DPIA {dpia['dpia_id']} for {operation} is overdue for review")
    return dpia

def score_credit_limit(applicant_summary: str) -> str:
    dpia = require_dpia("credit_limit_scoring")
    log.info("credit_limit_scoring running under %s", dpia["dpia_id"])
    resp = client.chat.completions.create(
        model="gpt-4o", messages=[{"role": "user", "content": f"Suggest a credit limit band (A-E) for:\n{applicant_summary}"}]
    )
    return resp.choices[0].message.content.strip()

