import OpenAI from "openai";

const client = new OpenAI();

type DpiaRecord = { dpiaId: string; approvedOn: Date; reviewDue: Date; approvedBy: string };

// High-risk processing operations need a signed-off DPIA before they may run.
const dpiaRegister: Record<string, DpiaRecord> = {
  creditLimitScoring: { dpiaId: "DPIA-2026-014", approvedOn: new Date("2026-03-02"), reviewDue: new Date("2027-03-02"), approvedBy: "dpo@example.eu" },
};

export function requireDpia(operation: string): DpiaRecord {
  const dpia = dpiaRegister[operation];
  if (!dpia) throw new Error(`No DPIA on record for ${operation}`);
  if (dpia.reviewDue < new Date()) throw new Error(`DPIA ${dpia.dpiaId} for ${operation} is overdue for review`);
  return dpia;
}

export async function scoreCreditLimit(applicantSummary: string): Promise<string> {
  const dpia = requireDpia("creditLimitScoring");
  console.info(`creditLimitScoring running under ${dpia.dpiaId}`);
  const resp = await client.chat.completions.create({
    model: "gpt-4o",
    messages: [{ role: "user", content: `Suggest a credit limit band (A-E) for:\n${applicantSummary}` }],
  });
  return (resp.choices[0].message.content ?? "").trim();
}

