  "We use an artificial intelligence system to help decide whether to offer you auto insurance " +
  "and at what premium. It is a substantial factor in this decision. " +
  "Contact ai-questions@example.com to learn more.";

export type Application = { summary: string; aiDisclosureVersion?: string; aiDisclosureShownAt?: string };

export class DisclosureNotShownError extends Error {}

