  const resp = await client.chat.completions.create({ model: "gpt-4o", messages: [
    { role: "system", content: "Answer APPROVE or DECLINE for this insurance application." },
    { role: "user", content: application.summary },
  ] });
  return (resp.choices[0].message.content ?? "").trim();
}

