import { randomUUID } from "node:crypto";
import OpenAI from "openai";

const client = new OpenAI();
const MODEL = "gpt-4o-2024-08-06";

type LoanOutcome = {
  id: string; applicantId: string; model: string; decidedAt: string;
  decision: "approve" | "deny"; principalReasons: string[]; dataUsed: string[];
};
const decisions = new Map<string, LoanOutcome>();

export async function decideLoan(applicant: { id: string } & Record<string, unknown>): Promise<LoanOutcome> {
  const resp = await client.chat.completions.create({ model: MODEL, response_format: { type: "json_object" }, messages: [
    { role: "system", content: "Return JSON with decision (approve|deny), principalReasons (list of strings) and dataUsed (list of applicant fields you relied on)." },
    { role: "user", content: JSON.stringify(applicant) },
  ] });
  const result = JSON.parse(resp.choices[0].message.content ?? "{}");
  const record: LoanOutcome = { id: randomUUID(), applicantId: applicant.id, model: MODEL, decidedAt: new Date().toISOString(), ...result };
  decisions.set(record.id, record);
  return record;
}

export function explainDecision(decisionId: string): string {
  const record = decisions.get(decisionId)!;
  if (record.decision !== "deny") return "Your application was approved.";
  return `Your application was denied. Principal reasons: ${record.principalReasons.join("; ")}. Information we used: ${record.dataUsed.join(", ")}.`;
}

