import Database from "better-sqlite3";

const db = new Database("hiring.db");
const ADS_RECORD_RETENTION_MS = 4 * 365 * 24 * 60 * 60 * 1000; // keep ADS records for at least four years
const IMPACT_RATIO_THRESHOLD = 0.8; // four-fifths rule

export function storeScreeningRecord(candidateId: string, inputs: object, score: number, advanced: boolean): void {
  const now = new Date();
  const retainUntil = new Date(now.getTime() + ADS_RECORD_RETENTION_MS);
  db.prepare("INSERT INTO ads_records (candidate_id, inputs, score, advanced, created_at, retain_until) VALUES (?, ?, ?, ?, ?, ?)")
    .run(candidateId, JSON.stringify(inputs), score, advanced ? 1 : 0, now.toISOString(), retainUntil.toISOString());
}

type GroupResult = { selectionRate: number; impactRatio: number; flagged: boolean };

export function runAdverseImpactTest(outcomes: Array<{ group: string; advanced: boolean }>): Record<string, GroupResult> {
  const totals: Record<string, number> = {};
  const selected: Record<string, number> = {};
  for (const { group, advanced } of outcomes) {
    totals[group] = (totals[group] ?? 0) + 1;
    selected[group] = (selected[group] ?? 0) + (advanced ? 1 : 0);
  }
  const rates = Object.fromEntries(Object.keys(totals).map((g) => [g, selected[g] / totals[g]]));
  const best = Math.max(...Object.values(rates)) || 1;
  const report = Object.fromEntries(Object.entries(rates).map(([g, rate]) => [
    g, { selectionRate: rate, impactRatio: rate / best, flagged: rate / best < IMPACT_RATIO_THRESHOLD },
  ]));
  db.prepare("INSERT INTO bias_audits (run_at, report) VALUES (?, ?)").run(new Date().toISOString(), JSON.stringify(report));
  return report;
}

