import OpenAI from "openai";

const client = new OpenAI();

interface Candidate {
  id: string;
  resumeText: string;
}

async function scoreCandidate(resumeText: string, jobDescription: string): Promise<number> {
  const resp = await client.chat.completions.create({
    model: "gpt-4o-mini",
    messages: [
      { role: "system", content: "Score how well the resume fits the job from 0 to 100. Reply with the number only." },
      { role: "user", content: `JOB:\n${jobDescription}\n\nRESUME:\n${resumeText}` },
    ],
  });
  return Number((resp.choices[0].message.content ?? "0").trim());
}

export async function shortlist(candidates: Candidate[], jobDescription: string, topN = 10) {
  const scored = [];
  for (const c of candidates) scored.push({ ...c, score: await scoreCandidate(c.resumeText, jobDescription) });
  return scored.sort((a, b) => b.score - a.score).slice(0, topN);
}

